WITH recent_subscriptions AS (SELECT * FROM subscriptions WHERE start_date <= '2025-09-01'), subscriptions_stats AS (SELECT YEAR(start_date) AS start_year, SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END) AS premium_count, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled FROM recent_subscriptions GROUP BY YEAR(start_date)) SELECT start_year, premium_count, pct_cancelled FROM subscriptions_stats WHERE premium_count < 52
